// Some portions generated by Claude
import test from "node:test";
import assert from "node:assert/strict";
import { parseSparqlResponse } from "../../../main/frontend/graph-explorer/rdf-results.ts";
test("malformed successful JSON is rejected before bindings reach the renderer", () => {
  for (const value of [
    null,
    [],
    {},
    { results: { bindings: {} } },
    { results: { bindings: [null] } },
    { results: { bindings: ["bad"] } },
  ])
    assert.throws(
      () => parseSparqlResponse(JSON.stringify(value)),
      /SPARQL Results JSON/,
    );
  const result = parseSparqlResponse(
    JSON.stringify({
      head: { vars: ["s", "p", "o"] },
      results: { bindings: [] },
    }),
  );
  assert.deepEqual(result.results.bindings, []);
});
